function openSettings(){const b=currentBoard();settingsDraft={title:b.title,columns:clone(b.columns),tags:[...b.tags]};$('#settings-title').value=b.title;renderSettingsColumns();renderSettingsTags();renderQa();$('#self-test-output').hidden=true;openDialog('settings-dialog')}
function renderSettingsColumns(){const b=currentBoard();$('#columns-settings').innerHTML=settingsDraft.columns.map((c,i)=>{const count=b.tasks.filter(t=>t.status===c.id).length;return`<div class="column-setting"><input data-column-name="${esc(c.id)}" value="${esc(c.title)}" maxlength="28" aria-label="Nombre de columna"><button class="mini-button" type="button" data-column-up="${esc(c.id)}" ${i===0?'disabled':''}>↑</button><button class="mini-button" type="button" data-column-down="${esc(c.id)}" ${i===settingsDraft.columns.length-1?'disabled':''}>↓</button><button class="mini-button" type="button" data-column-delete="${esc(c.id)}" ${count?'disabled':''} title="${count?'Vacía la columna antes de eliminarla':'Eliminar columna'}">×</button></div>`}).join('');$('#add-column').disabled=settingsDraft.columns.length>=MAX_COLUMNS}
function renderSettingsTags(){$('#tag-settings').innerHTML=settingsDraft.tags.map(tag=>`<span class="tag-manage">${esc(tag)}<button type="button" data-tag-delete="${esc(tag)}" aria-label="Eliminar ${esc(tag)}">×</button></span>`).join('');const input=$('#new-tag-input');input.disabled=settingsDraft.tags.length>=MAX_TAGS;input.placeholder=settingsDraft.tags.length>=MAX_TAGS?'Máximo 8 tags':'Nuevo tag…'}
function addColumn(){if(settingsDraft.columns.length>=MAX_COLUMNS)return showToast('Máximo 5 columnas por tablero');settingsDraft.columns.push({id:uid('col'),title:`Columna ${settingsDraft.columns.length+1}`});renderSettingsColumns()}
function deleteDraftColumn(id){if(settingsDraft.columns.length<=1)return showToast('Debe quedar al menos una columna');if(currentBoard().tasks.some(t=>t.status===id))return showToast('Vacía la columna antes de eliminarla');settingsDraft.columns=settingsDraft.columns.filter(c=>c.id!==id);renderSettingsColumns()}
function moveDraftColumn(id,dir){const i=settingsDraft.columns.findIndex(c=>c.id===id),j=i+dir;if(i<0||j<0||j>=settingsDraft.columns.length)return;[settingsDraft.columns[i],settingsDraft.columns[j]]=[settingsDraft.columns[j],settingsDraft.columns[i]];renderSettingsColumns()}
function addDraftTag(tag){tag=tag.trim().replace(/\s+/g,' ').slice(0,24);if(!tag)return;if(settingsDraft.tags.length>=MAX_TAGS)return showToast('Máximo 8 tags por tablero');if(settingsDraft.tags.some(x=>x.toLowerCase()===tag.toLowerCase()))return showToast('Ese tag ya existe');settingsDraft.tags.push(tag);$('#new-tag-input').value='';renderSettingsTags()}
function deleteDraftTag(tag){settingsDraft.tags=settingsDraft.tags.filter(x=>x!==tag);renderSettingsTags()}
function saveSettings(){const b=currentBoard(),title=$('#settings-title').value.trim();if(!title)return showToast('El tablero necesita un nombre');$$('[data-column-name]').forEach(input=>{const c=settingsDraft.columns.find(x=>x.id===input.dataset.columnName);if(c)c.title=input.value.trim()||'Sin nombre'});const removedTags=b.tags.filter(x=>!settingsDraft.tags.includes(x));commit('Configurar tablero',()=>{b.title=title.slice(0,48);b.columns=clone(settingsDraft.columns);b.tags=[...settingsDraft.tags];if(removedTags.length)b.tasks.forEach(t=>t.tags=t.tags.filter(x=>b.tags.includes(x)));if(!b.columns.some(c=>c.id===state.activeColumnId))state.activeColumnId=b.columns[0].id},'Tablero actualizado');closeDialog('settings-dialog')}
